// Test fixture: the RESOLVER-WRAPPER shape used by essentially every native npm package.
//
// `bindings@1.5.0` ends at `requireFunc(n)` and `node-gyp-build@4.8.4` at
// `runtimeRequire(load.resolve(dir))` — in both cases a plain `require()` of another
// package's `.node` file, executed from the HELPER's own source file. That makes the nearest
// package frame on the stack the helper, not the package whose addon is being loaded, which
// is why capwall's native gate charges the load to the addon's owning package as well as to
// the caller (see core/src/loader/native.ts).
const path = require("path");

module.exports = function load(dir) {
  return require(path.join(dir, "build", "Release", "fixture-addon.node"));
};
